/* 19/11/2026: "Grupos do usuário" abre o popup da lista dupla de grupos do usuário selecionado; ao fechar, recarrega o grid. */
(function () {
  var t = document.getElementById('userBatchGrid'), b = document.querySelector('[data-user-grupos]');
  if (!t || !b) return;
  function sel() { var r = t.querySelector('tbody tr.selected'); var k = r ? String(r.getAttribute('data-key') || '') : ''; return /^\d+$/.test(k) ? k : ''; }
  t.addEventListener('click', function () { setTimeout(function () { b.disabled = !sel(); }, 0); });
  b.addEventListener('click', function () {
    var k = sel(); if (!k) return;
    var url = new URL('seguranca_usuario_grupos.php?codusuario=' + k, window.location.href).toString(), host = window.top || window, m = null;
    if (host.GreenPortalPopups && typeof host.GreenPortalPopups.transacao90 === 'function') m = host.GreenPortalPopups.transacao90({ titulo: <?= json_encode($gpTxG('Grupos do usuário','User groups','Grupos del usuario'), JSON_UNESCAPED_UNICODE) ?>, url: url });
    else window.open(url, '_blank');
    if (m && typeof m.on === 'function') m.on('hidden.bs.modal', function () { var r = document.querySelector('[data-reload-grid]'); if (r) r.click(); });
  });
}());
/* GER-1/GER-18 (12/11/2026): "Idioma e foto" abre o popup do usuário selecionado (idioma do cadastro e remover foto). */
(function () {
  var t = document.getElementById('userBatchGrid'), b = document.querySelector('[data-user-prefs]');
  if (!t || !b) return;
  function sel() { var r = t.querySelector('tbody tr.selected'); var k = r ? String(r.getAttribute('data-key') || '') : ''; return /^\d+$/.test(k) ? k : ''; }
  t.addEventListener('click', function () { setTimeout(function () { b.disabled = !sel(); }, 0); });
  b.addEventListener('click', function () {
    var k = sel(); if (!k) return;
    var url = new URL('seguranca_usuario_preferencias.php?codusuario=' + k, window.location.href).toString(), host = window.top || window;
    if (host.GreenPortalPopups && typeof host.GreenPortalPopups.transacao90 === 'function') host.GreenPortalPopups.transacao90({ titulo: <?= adm_js('Idioma e foto do usuário') ?>, url: url });
    else window.open(url, '_blank');
  });
}());
</script>
